      "Những ánh mắt dòm ngó bắt đầu chĩa về phía kẻ lạ mặt. Kẻ thì liếc nhìn rồi vội quay đi, kẻ thì kề tai thì thầm. Hắn cho đó là sự hèn mọn của bầy cừu trước kẻ săn mồi, và nó chỉ khoét sâu thêm nỗi chán ghét. Ít nhất, hắn tự nhủ mình chẳng bận tâm.",
      "Bước chân hắn vô thức nhanh hơn, cho tới khi sự chú ý va phải một công trình khổng lồ: một ngọn tháp đá sừng sững ghim thẳng vào trung tâm khu chợ. Có lẽ nó đã đứng đó từ lúc hắn bước qua cổng, chỉ là hắn chưa từng để mắt tới. Trên nền gạch tàn tạ dưới chân tháp, một dòng chữ được đục đẽo thô kệch.",
