      "Mang trong mình sự kiêu ngạo tột cùng, hắn chỉ khoanh tay đứng nhìn. Hắn muốn xem sinh vật mỏng manh kia sẽ ra sao khi ngẩng mặt lên.",
      "“ Hình như ngươi không nhìn thấy ta thì phải? “",
      "Không một lời hồi đáp. Thậm chí một cái liếc mắt dè chừng cũng không. Sự câm lặng ấy xé toạc lòng tự tôn của hắn như một nhát dao.",
      "Người nọ thu dọn xong liền đứng thẳng dậy, hờ hững lướt qua hắn như thể hắn chỉ là một pho tượng đá. Hắn sững người. Chưa từng có sinh vật nào trên cõi đời này dám phớt lờ hắn đến thế.",
      "“ Ngươi dám phớt lờ lời của ta như thế sao? “",
      "Bóng áo choàng khựng lại. Cuối cùng thì khoảnh khắc hắn chờ đợi cũng đến. Hắn đã mường tượng ra một khuôn mặt nhợt nhạt, một sự run rẩy mà bọn phàm nhân vốn phải có. Nhưng hắn chưa từng đoán được thân phận của kẻ trước mặt, cho tới khi một giọng nói nhẹ tênh vang lên từ dưới lớp mũ trùm.",
